from mcp.server import MCPServer
from mcp.server.mcpserver.exceptions import ToolError

mcp = MCPServer("orders")

ORDERS = {"A-1001": {"status": "shipped", "total_cents": 4250}}


@mcp.tool()
def get_order(order_id: str) -> str:
    """Look up one order by id. Read-only. Returns status and total in cents."""
    order = ORDERS.get(order_id)
    if order is None:
        raise ToolError(f"No order {order_id!r}. Order ids look like A-1001.")
    return f"{order_id}: {order['status']}, total {order['total_cents']} cents"


if __name__ == "__main__":
    mcp.run()  # stdio; mcp.run(transport="streamable-http", port=8000) serves HTTP

import { createMcpHandler, McpServer } from '@modelcontextprotocol/server';
import * as z from 'zod/v4';

const ORDERS: Record<string, { status: string; totalCents: number }> = {
    'A-1001': { status: 'shipped', totalCents: 4250 }
};

export const handler = createMcpHandler(() => {
    const server = new McpServer({ name: 'orders', version: '1.0.0' });
    server.registerTool(
        'get_order',
        {
            description: 'Look up one order by id. Read-only. Returns status and total in cents.',
            inputSchema: z.object({ order_id: z.string().describe('Order id, for example A-1001') })
        },
        async ({ order_id }) => {
            const order = ORDERS[order_id];
            if (!order) {
                return { content: [{ type: 'text', text: `No order ${order_id}. Order ids look like A-1001.` }], isError: true };
            }
            return { content: [{ type: 'text', text: `${order_id}: ${order.status}, total ${order.totalCents} cents` }] };
        }
    );
    return server;
});
